import csv
import io
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    try:
        for record in reader:
            if record:
                records.append([value for value in record])
    except csv.Error:
        pass

    if not records:
        return {"columns": [], "rows": []}

    header_index = 0
    for index, record in enumerate(records[:20]):
        if len(record) >= 2 and any(any(char.isalpha() for char in cell) for cell in record):
            header_index = index
            break

    columns = records[header_index][:]
    data_rows = records[header_index + 1:]
    width = max(17, len(columns), *(len(row) for row in data_rows)) if data_rows else max(17, len(columns))

    while len(columns) < width:
        columns.append("Column {}".format(len(columns) + 1))

    normalized_rows = []
    for row in data_rows:
        normalized_rows.append(row + [""] * (width - len(row)))

    return {"columns": columns, "rows": normalized_rows}
